#include "GizmoRenderer.h"
#include <glad/glad.h>
#include <cmath>
#include <vector>

namespace { const char* vs="#version 330 core\nlayout(location=0)in vec3 p;uniform mat4 viewProjection;void main(){gl_Position=viewProjection*vec4(p,1.0);}"; const char* fs="#version 330 core\nuniform vec3 color;out vec4 outColor;void main(){outColor=vec4(color,1.0);}"; }
void GizmoRenderer::Initialize(){unsigned int v=glCreateShader(GL_VERTEX_SHADER),f=glCreateShader(GL_FRAGMENT_SHADER);glShaderSource(v,1,&vs,nullptr);glShaderSource(f,1,&fs,nullptr);glCompileShader(v);glCompileShader(f);program_=glCreateProgram();glAttachShader(program_,v);glAttachShader(program_,f);glLinkProgram(program_);glDeleteShader(v);glDeleteShader(f);glGenVertexArrays(1,&vao_);glGenBuffers(1,&vbo_);viewProjectionLocation_=glGetUniformLocation(program_,"viewProjection");colorLocation_=glGetUniformLocation(program_,"color");}
void GizmoRenderer::Begin(const GizmoCamera& camera,const Vector3& origin,float size,const Quaternion& orientation){viewProjection_=camera.projection*camera.view;origin_=origin;size_=size;orientation_=orientation;glUseProgram(program_);glUniformMatrix4fv(viewProjectionLocation_,1,GL_FALSE,viewProjection_.value);glBindVertexArray(vao_);glBindBuffer(GL_ARRAY_BUFFER,vbo_);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,sizeof(Vector3),nullptr);glEnableVertexAttribArray(0);glDisable(GL_DEPTH_TEST);}
void GizmoRenderer::Draw(const std::vector<Vector3>& vertices,const Vector3& color,float width,bool loop){if(vertices.empty())return;glBufferData(GL_ARRAY_BUFFER,vertices.size()*sizeof(Vector3),vertices.data(),GL_DYNAMIC_DRAW);glUniform3f(colorLocation_,color.x,color.y,color.z);glLineWidth(width);glDrawArrays(loop?GL_LINE_LOOP:GL_LINE_STRIP,0,(GLsizei)vertices.size());}
void GizmoRenderer::DrawMoveAxis(GizmoAxis axis,bool highlighted){const Vector3 localDirection=axis==GizmoAxis::X?Vector3{1,0,0}:axis==GizmoAxis::Y?Vector3{0,1,0}:Vector3{0,0,1};const Vector3 direction=Normalize(orientation_.Rotate(localDirection));const Vector3 color=axis==GizmoAxis::X?Vector3{0.9f,0.05f,0.04f}:axis==GizmoAxis::Y?Vector3{0.05f,0.85f,0.08f}:Vector3{0.05f,0.3f,0.95f};const Vector3 tip=origin_+direction*size_;std::vector<Vector3> line={origin_,tip};Draw(line,highlighted?Vector3{1,1,0}:color,highlighted?5.0f:3.0f,false);const Vector3 side=Normalize(std::fabs(direction.y)<0.9f?Cross(direction,{0,1,0}):Cross(direction,{1,0,0}));const float head=size_*0.13f;Draw({tip,tip-direction*head+side*head*0.5f,tip,tip-direction*head-side*head*0.5f},highlighted?Vector3{1,1,0}:color,highlighted?5.0f:3.0f,false);}
void GizmoRenderer::DrawRotateRing(GizmoAxis axis,bool highlighted){const Vector3 localNormal=axis==GizmoAxis::X?Vector3{1,0,0}:axis==GizmoAxis::Y?Vector3{0,1,0}:Vector3{0,0,1};const Vector3 normal=Normalize(orientation_.Rotate(localNormal));const Vector3 basis=std::fabs(normal.y)<0.9f?Normalize(Cross(normal,{0,1,0})):Normalize(Cross(normal,{1,0,0}));const Vector3 second=Normalize(Cross(normal,basis));std::vector<Vector3> vertices;for(int i=0;i<64;++i){const float a=6.283185307f*float(i)/64.0f;vertices.push_back(origin_+(basis*std::cos(a)+second*std::sin(a))*size_);}const Vector3 color=axis==GizmoAxis::X?Vector3{0.9f,0.05f,0.04f}:axis==GizmoAxis::Y?Vector3{0.05f,0.85f,0.08f}:Vector3{0.05f,0.3f,0.95f};Draw(vertices,highlighted?Vector3{1,1,0}:color,highlighted?5.0f:3.0f,true);}
void GizmoRenderer::End(){glEnable(GL_DEPTH_TEST);glDisableVertexAttribArray(0);}
void GizmoRenderer::Shutdown(){if(vbo_)glDeleteBuffers(1,&vbo_);if(vao_)glDeleteVertexArrays(1,&vao_);if(program_)glDeleteProgram(program_);vbo_=vao_=program_=0;}
